let mySize;

// a shader variable
let theShader;

function preload(){
	theShader = new p5.Shader(this.renderer,vert,frag)
}

function setup() {
		mySize = min(windowWidth, windowHeight)*1.0;
  // shaders require WEBGL mode to work
  createCanvas(mySize/16*11, mySize, WEBGL);
  noStroke();
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", millis() / 500.0); 
  theShader.setUniform("u_frame", frameCount/10.0);
  theShader.setUniform("u_mouse", [mouseX/1.0, map(mouseY, 0, height, height, 0)/1.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized(){
  resizeCanvas(windowWidth, windowHeight);
}

